VALUES (71041, 'tt0052295', NULL, 'The Tiger of Eschnapur', 'Der Tiger von Eschnapur', 'movie', 1959, 'https://image.tmdb.org/t/p/w500/eOQud8hEPgBJ82AmJ2HPjZLmpnz.jpg', 'https://image.tmdb.org/t/p/original/mirBMR2y7tzcORkNo0IltcmDzsA.jpg', 'In Eschnapur, a German architect saves the life of the Maharajah''s favorite temple dancer and becomes Maharajah''s friend but their friendship is tested when the architect and the dancer fall in-love, triggering the Maharajah''s vengeful ire.', NULL, NULL, 1.9789, 6.3, 0, 1.01, '2026-10-14 23:31:09', '2026-10-14 23:31:09')
