VALUES (3031, 'tt0870039', NULL, 'Growing Up Creepie', 'Growing Up Creepie', 'tv', 2006, 'https://image.tmdb.org/t/p/w500/q71a8HeI6Np7OFZhBUDJ0Hkphgd.jpg', 'https://image.tmdb.org/t/p/original/lyoNCMcq1qGNv67HwVYdq0na71m.jpg', 'Growing Up Creepie was an animated television series made in the USA and Canada by Mike Young Productions and produced by Discovery Kids. In other countries, the series was simply titled Creepie. The series aired 52 episodes, and it would have aired more, but Discovery Kids was replaced with The Hub.', NULL, NULL, 3.2784, 7.3, 0, 10.55, '2026-10-14 23:31:09', '2026-10-14 23:31:09')
