VALUES (739986, 'tt2353868', NULL, 'True Spirit', 'True Spirit', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/5qntAorVEzixuYOIPMCGwDiuGkd.jpg', 'https://image.tmdb.org/t/p/original/dA34DDakXgvbjnyKocOcLJtKz0.jpg', 'When the tenacious young sailor Jessica Watson sets out to be the youngest person to sail solo, nonstop and unassisted around the world, many expect her to fail. With the support of her sailing coach and mentor Ben Bryant and her parents, Jessica is determined to accomplish what was thought to be impossible, navigating some of the world’s most challenging stretches of ocean over the course of 210 days.', NULL, NULL, 7.0541, 7.0, 0, 9.52, '2026-10-14 23:31:09', '2026-10-14 23:31:09')
