VALUES (717157, 'tt14075830', NULL, 'Last Man Fishing', 'Last Man Fishing', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/3OTaZWHE00Wk8FB0ZaRHjdnfPLB.jpg', NULL, 'LAST MAN FISHING is a cinematic look at the vastly changing seafood system through the lens of small-scale fishermen across the United States. Narrated by best-selling author Mark Bittman, the film explores the dichotomy between the industrial model and sustainable fishing methods that focus on conservation and quality.', NULL, NULL, 0.9177, 0.0, 0, 8.51, '2026-10-14 23:31:09', '2026-10-14 23:31:09')
