VALUES (16515, 'tt0028691', NULL, 'Captains Courageous', 'Captains Courageous', 'movie', 1937, 'https://image.tmdb.org/t/p/w500/qhJNHLwIcMqDKBwsr9uMDOumO33.jpg', 'https://image.tmdb.org/t/p/original/2eKw8s2m2MZv0fLrmavNDZUS4BE.jpg', 'Harvey, the arrogant and spoiled son of an indulgent absentee-father, falls overboard from a transatlantic steamship and is rescued by a fishing vessel on the Grand Banks. Harvey fails to persuade them to take him ashore, nor convince the crew of his wealth. The captain offers him a low-paid job, until they return to port, as part of the crew that turns him into a mature, considerate young man.', NULL, NULL, 2.6625, 7.4, 0, 10.51, '2026-10-14 23:31:09', '2026-10-14 23:31:09')
