VALUES (117488, 'tt11041332', NULL, 'Yellowjackets', 'Yellowjackets', 'tv', 2021, 'https://image.tmdb.org/t/p/w500/xRnGrn7Z7SC0KIBodocoU1QgDZF.jpg', 'https://image.tmdb.org/t/p/original/ibFWJDWS8cTO6s2vZVd2uKDm8p.jpg', 'This equal parts survival epic, psychological horror story and coming-of-age drama tells the saga of a team of wildly talented high school girls soccer players who become the (un)lucky survivors of a plane crash deep in the remote northern wilderness. The series chronicles their descent from a complicated but thriving team to savage clans, while also tracking the lives they’ve attempted to piece back together nearly 25 years later.', NULL, NULL, 28.6725, 7.446, 0, 29.0036, '2026-07-15 12:01:52', '2026-10-14 23:31:09')
