VALUES (565, 'tt0298130', NULL, 'The Ring', 'The Ring', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/AeRpUynJKDpJveklBJipOYrVxCS.jpg', 'https://image.tmdb.org/t/p/original/6tuNQ16hC4Qp7wjTweKzUnnLBkI.jpg', 'Journalist Rachel Keller investigates a strange videotape that may be behind the untimely deaths of four teenagers. There is an urban legend about this tape: the viewer will die seven days after watching it. Rachel tracks down the video... and watches it. Now she has just seven days to unravel the mystery of the Ring in order to save herself and her son.', NULL, NULL, 14.1533, 6.708, 0, 7.01683076923076924e+01, '2026-07-15 12:01:52', '2026-10-14 23:31:09')
