VALUES (11481, 'tt0059646', NULL, 'Repulsion', 'Repulsion', 'movie', 1965, 'https://image.tmdb.org/t/p/w500/dtyCKEPLqv9wxyVazL4b843vtUb.jpg', 'https://image.tmdb.org/t/p/original/5rbPwIdEZTyLTkpAgvGdacgCr7T.jpg', 'Beautiful young manicurist Carole suffers from androphobia (the pathological fear of interaction with men). When her sister and roommate, Helen, leaves their London flat to go on an Italian holiday with her married boyfriend, Carole withdraws into her apartment. She begins to experience frightful hallucinations, her fear gradually mutating into madness.', NULL, NULL, 3.9629, 7.364, 0, 1.09011111111111116e+01, '2026-07-15 12:01:52', '2026-10-14 23:31:09')
