VALUES (575776, 'tt7557108', NULL, 'Saint Maud', 'Saint Maud', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/ArNYeeDFLVye7JpqLElYdbE6fOa.jpg', 'https://image.tmdb.org/t/p/original/1WKxsnrhLoKPHcTyph7lhZnAMjR.jpg', 'Having recently found God, self-effacing young nurse Maud arrives at a plush home to care for Amanda, a hedonistic dancer left frail from a chronic illness. When a chance encounter with a former colleague throws up hints of a dark past, it becomes clear there is more to sweet Maud than meets the eye.', NULL, NULL, 2.3734, 6.542, 0, 44.3345, '2026-07-15 12:01:52', '2026-10-14 23:31:09')
