VALUES (4348, 'tt0414387', NULL, 'Pride & Prejudice', 'Pride & Prejudice', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/o8UhmEbWPHmTUxP0lMuCoqNkbB3.jpg', 'https://image.tmdb.org/t/p/original/1Onam6oWyFAUCcoxtdWkACtEiNr.jpg', 'A story of love and life among the landed English gentry during the Georgian era. Mr. Bennet is a gentleman living in Hertfordshire with his overbearing wife and five daughters, but if he dies their house will be inherited by a distant cousin whom they have never met, so the family''s future happiness and security is dependent on the daughters making good marriages.', NULL, NULL, 17.6921, 8.056, 0, 1.68921428571428577e+01, '2026-07-30 18:28:39', '2026-10-14 23:31:09')
