VALUES (1457, 'tt0112130', NULL, 'Pride and Prejudice', 'Pride and Prejudice', 'tv', 1995, 'https://image.tmdb.org/t/p/w500/7od3Mob2qu5lL1l5RsdV6xuEquw.jpg', 'https://image.tmdb.org/t/p/original/6d1yCaiI7AexmtGX2vORqEbZ0oV.jpg', 'Set in England in the early 19th century, Pride and Prejudice tells the story of Mr and Mrs Bennet''s five unmarried daughters after the rich and eligible Mr Bingley and his status-conscious friend, Mr Darcy, have moved into their neighbourhood. While Bingley takes an immediate liking to the eldest Bennet daughter, Jane, Darcy has difficulty adapting to local society and repeatedly clashes with the second-eldest Bennet daughter, Elizabeth.', NULL, NULL, 11.9375, 8.199, 0, 8.24, '2026-08-03 14:31:56', '2026-10-14 23:31:09')
