VALUES (41791, 'tt0102456', NULL, 'Mississippi Masala', 'Mississippi Masala', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/b2Gks4Stt98FRI5isaL6Wu1luhh.jpg', 'https://image.tmdb.org/t/p/original/PFrzqXuT0yEGEmcbXDwPOUKCsS.jpg', 'Years after her Indian family was forced to flee their Uganda home, twentysomething Mina finds herself co-operating a motel in the faraway land of Mississippi. Her passionate romance with charming Black carpet cleaner Demetrius challenges the prejudices of their conservative families and exposes the rifts between the region''s Indian and African-American communities.', NULL, NULL, 2.8486, 6.385, 0, 8.62399999999999877e+00, '2026-08-18 01:44:45', '2026-10-14 23:31:09')
