VALUES (1479, 'tt0106579', NULL, 'Clean, Shaven', 'Clean, Shaven', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/kpMXYy0L2GHrIVyDF0HkEiDK1Wd.jpg', 'https://image.tmdb.org/t/p/original/sL364DOfbKPNwI3BHW0KDYgc2Ti.jpg', 'Peter Winter is a young schizophrenic who is desperately trying to get his daughter back from her adoptive family. He attempts to function in a world that, for him, is filled with strange voices, electrical noise, disconcerting images, and jarringly sudden emotional shifts. During his quest, he runs afoul of the law and an ongoing murder investigation.', NULL, NULL, 1.9263, 6.491, 0, 6.275, '2026-09-01 03:44:37', '2026-10-14 23:31:09')
